REVOKE EXECUTE ON FUNCTION public.fn_me_email_eligible(text) FROM anon,authenticated;
GRANT EXECUTE ON FUNCTION public.fn_me_email_eligible(text) TO service_role;
CREATE OR REPLACE FUNCTION public.fn_referral_action(p_referral_id uuid,p_action text) RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_catalog AS $$ DECLARE r public.referrals%ROWTYPE; owner_id uuid; BEGIN SELECT * INTO r FROM public.referrals WHERE id=p_referral_id; IF auth.uid() IS NULL OR r.referrer_id IS DISTINCT FROM auth.uid() OR p_action NOT IN ('nudge','dispute_submitted') THEN RAISE EXCEPTION 'not_authorized'; END IF; IF NOT public.fn_rate_bucket_hit('ref_action:'||auth.uid(),interval '1 day',5) THEN RAISE EXCEPTION 'rate_limited'; END IF; SELECT user_id INTO owner_id FROM public.businesses WHERE id=r.business_id; IF p_action='dispute_submitted' THEN PERFORM public.fn_create_audit_entry(r.id,auth.uid(),p_action,jsonb_build_object('previous_status',r.status)); END IF; PERFORM public.fn_create_notification(owner_id,CASE WHEN p_action='nudge' THEN 'Referral follow-up' ELSE 'Dispute submitted' END,'A referrer requested an update.',p_action,r.id); RETURN true; END $$;
REVOKE ALL ON FUNCTION public.fn_referral_action(uuid,text) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.fn_referral_action(uuid,text) TO authenticated;
CREATE OR REPLACE FUNCTION public.fn_security_business_audit() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_catalog AS $$ BEGIN IF NEW.verified IS DISTINCT FROM OLD.verified OR NEW.index_approved IS DISTINCT FROM OLD.index_approved THEN INSERT INTO public.audit_log(actor_id,event_type,payload) VALUES(coalesce(auth.uid(),NEW.user_id),'business_moderated',jsonb_build_object('business_id',NEW.id,'verified',NEW.verified,'index_approved',NEW.index_approved)); END IF; RETURN NEW; END $$;
CREATE TRIGGER trg_security_business_audit AFTER UPDATE ON public.businesses FOR EACH ROW EXECUTE FUNCTION public.fn_security_business_audit();
CREATE OR REPLACE FUNCTION public.fn_security_dispute_audit() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_catalog AS $$ BEGIN IF NEW.status IS DISTINCT FROM OLD.status AND public.has_role(auth.uid(),'admin') THEN PERFORM public.fn_create_audit_entry(NEW.id,auth.uid(),'dispute_resolved',jsonb_build_object('resolution',NEW.status)); END IF; RETURN NEW; END $$;
CREATE TRIGGER trg_security_dispute_audit AFTER UPDATE ON public.referrals FOR EACH ROW EXECUTE FUNCTION public.fn_security_dispute_audit();